<?php

declare(strict_types=1);

namespace App\Scan;

/**
 * Builds files the customer can copy as they are. Built from extracted facts, not generated by a model, so the output is valid.
 */
final class ReadyToPasteContent
{
    /** The AI crawlers the robots snippet allows. Same list as AiCrawlerAccessCheck. */
    private const AI_CRAWLERS = ['GPTBot', 'ChatGPT-User', 'ClaudeBot', 'PerplexityBot', 'Google-Extended', 'CCBot'];

    /** Placeholder profiles, used when the scan found no social links. The customer replaces them. */
    private const SAME_AS_EXAMPLES = [
        'https://www.linkedin.com/company/jouw-bedrijf',
        'https://www.youtube.com/@jouw-bedrijf',
        'https://www.instagram.com/jouw-bedrijf',
        'https://www.facebook.com/jouw-bedrijf',
        'https://x.com/jouw-bedrijf',
    ];

    /**
     * @param array<string, SiteMeta> $pageMetas keyed by page url
     */
    public function llmsTxt(string $homeUrl, SiteMeta $home, array $pageMetas): string
    {
        $lines = ['# '.$home->name($homeUrl), ''];

        if ('' !== $home->description) {
            $lines[] = '> '.$home->description;
            $lines[] = '';
        }

        $lines[] = '## Belangrijke pagina\'s';
        $lines[] = '';

        foreach ($pageMetas as $url => $meta) {
            $label = '' !== $meta->title ? $meta->title : $url;
            $description = '' !== $meta->description ? ': '.$meta->description : '';

            $lines[] = sprintf('- [%s](%s)%s', $label, $url, $description);
        }

        return implode("\n", $lines)."\n";
    }

    public function organizationJsonLd(string $homeUrl, SiteMeta $home): string
    {
        $data = array_filter([
            '@context' => 'https://schema.org',
            '@type' => 'Organization',
            'name' => $home->name($homeUrl),
            'url' => $homeUrl,
            'description' => $home->description,
            'sameAs' => [] === $home->sameAs ? self::SAME_AS_EXAMPLES : $home->sameAs,
        ], fn (mixed $value): bool => !(is_string($value) && '' === $value) && !(is_array($value) && [] === $value));

        return json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    }

    public function robotsSnippet(): string
    {
        $lines = [];
        foreach (self::AI_CRAWLERS as $crawler) {
            $lines[] = 'User-agent: '.$crawler;
            $lines[] = 'Allow: /';
            $lines[] = '';
        }

        return implode("\n", $lines);
    }
}
